/* Tutoki — interactive browser-only prototype. No accounts, uploads or messages leave this browser. */
(() => {
'use strict';
const $ = (s,r=document)=>r.querySelector(s);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2Z',chart:'M4 21V13M10 21V8M16 21V3M22 21H2',plus:'M12 5v14M5 12h14',arrow:'M4 12h16M14 6l6 6-6 6',back:'M20 12H4M10 6l-6 6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bulb:'M9 18h6M10 22h4M8 14a7 7 0 1 1 8 0l-1 4H9Z',chat:'M21 4H3v13h5v4l5-4h8Z',leaf:'M20 3C8 2 1 9 5 17s17 1 15-14ZM5 20l11-12',mic:'M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',upload:'M12 16V3M7 8l5-5 5 5M3 15v6h18v-6',file:'M14 2H5v20h14V7ZM14 2v5h5M8 12h8M8 16h6',copy:'M9 9h12v12H9ZM3 15V3h12',share:'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 22a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM9 10l6-4M9 14l6 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 2h6l1 4 4 1 2 5-3 3 1 4-5 3-3-3-4 1-3-5 3-3Z',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v.2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',mail:'M2 4h20v16H2ZM2 5l10 8L22 5',lock:'M6 10h12v12H6ZM8 10V6a4 4 0 0 1 8 0v4',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',logout:'M9 4H3v16h6M12 12h10M17 7l5 5-5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',edit:'m15 3 6 6L8 22l-6 1 1-6ZM12 6l6 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4M18 4h4',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',trophy:'M7 3h10v9a5 5 0 0 1-10 0ZM7 5H2v3a5 5 0 0 0 5 5M17 5h5v3a5 5 0 0 1-5 5M12 17v5M8 22h8',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6ZM8 12l3 3 5-6',volume:'M4 9h4l5-5v16l-5-5H4ZM17 7a8 8 0 0 1 0 10M20 4a12 12 0 0 1 0 16',download:'M12 2v14M7 11l5 5 5-5M3 17v5h18v-5',wifi:'M2 7a17 17 0 0 1 20 0M5 11a12 12 0 0 1 14 0M9 15a5 5 0 0 1 6 0M12 19h.01M3 3l18 18',menu:'M3 6h18M3 12h18M3 18h18',play:'m7 3 14 9-14 9Z',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',flag:'M4 22V3c7-4 9 4 16 0v11c-7 4-9-4-16 0',printer:'M6 8V2h12v6M6 17H2V8h20v9h-4M6 14h12v8H6Z',school:'m2 9 10-7 10 7M5 8v14h14V8M10 22v-6h4v6M8 11h1M15 11h1',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`;
const poses={teacher:['02-grupos.png',1568,535,120,220,330],detective:['05-detective.png',1672,95,201,310,221],think:['06-primero-tu.png',1671,53,350,325,240],wave:['04-entrada-estudiante.png',1671,80,210,270,265],celebrate:['11-avance-familias.png',1774,560,325,255,250],plant:['09-reto-comunidad.png',1672,60,187,313,276],speak:['08-defiendelo.png',1671,70,205,310,235],debate:['07-duelo.png',1671,80,253,270,257]};
function art(p='wave',cls=''){const [src,w,x,y,cw,ch]=poses[p]||poses.wave;return `<div class="art ${cls}" style="aspect-ratio:${cw}/${ch}" aria-hidden="true"><img src="assets/${src}" alt="" draggable="false" style="width:${w/cw*100}%;left:${-x/cw*100}%;top:${-y/ch*100}%"></div>`;}
const brand=()=>`<a class="brand spark" href="#/" aria-label="Tutoki, inicio"><span class="brand-mark"></span>Tutoki</a>`;
const btn=(text,to,kind='primary',icon='arrow')=>`<a class="btn ${kind}" href="#${to}">${esc(text)}${icon?ico(icon):''}</a>`;
const action=(text,id,kind='primary',icon='')=>`<button class="btn ${kind}" data-action="${id}">${icon?ico(icon):''}${esc(text)}</button>`;
const field=(label,name,placeholder='',value='',type='text',required=true)=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${required?'required':''}></div>`;
const area=(label,name,placeholder='',value='',required=true)=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(value)}</textarea></div>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('tutoki-prototype-v1')||'{}')}catch{}
let state={role:'teacher',name:'Ana',alias:'Alex',group:'5.º A',grade:'5.º',level:'Primaria',created:false,published:false,activity:'detective',topic:'¿Qué necesitan las plantas?',file:'Las plantas.pdf',mode:'individual',tab:'activities',avatar:'detective',consent:false,answers:{},submitted:{},feedback:'Comparaste las plantas. ¿Qué otra condición mantendrías igual?',reviewed:false,large:false,motion:false,read:false,...saved};
const persist=()=>{try{localStorage.setItem('tutoki-prototype-v1',JSON.stringify(state))}catch{}};
let current='',recording=false,recorder=null,recordedUrl=null;
const go=p=>{if(location.hash==='#'+p)render();else location.hash=p};
const activities=[{id:'detective',name:'Detective',icon:'search',pose:'detective',desc:'Analiza información, busca evidencias y saca conclusiones.'},{id:'primero',name:'Primero tú',icon:'bulb',pose:'think',desc:'Piensa, analiza y formula tu propia respuesta.'},{id:'defiendelo',name:'Defiéndelo',icon:'mic',pose:'speak',desc:'Explica cómo llegaste a tu idea.'},{id:'comunidad',name:'Reto comunidad',icon:'users',pose:'plant',desc:'Aplica lo que sabes para proponer soluciones.'},{id:'duelo',name:'Duelo',icon:'chat',pose:'debate',desc:'Contrasta posturas y argumenta con evidencia.'}];
const activityName=id=>activities.find(a=>a.id===id)?.name||'Detective';
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3200)}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-title"><h2>${title}</h2><button class="circle-button" data-action="close-modal" aria-label="Cerrar">${ico('close')}</button></div>${html}`;$('#modal').showModal()}
function preview(){return `<div class="preview-bar"><span class="preview-label">Vista previa · Datos de ejemplo</span><div class="preview-right"><button data-action="tour">Explorar pantallas ${ico('down')}</button><button data-action="help" aria-label="Ayuda">${ico('help')}</button></div></div>`}
function teacher(content,active='home',step=0){return `${preview()}<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Navegación principal">${[['home','home','Inicio','/docente'],['groups','users','Mis grupos','/docente/grupo'],['activities','book','Actividades','/docente/actividades'],['progress','chart','Progreso','/docente/progreso']].map(([id,ic,name,path])=>`<a href="#${path}" class="${id===active?'active':''}">${ico(ic)}${name}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="side-tip">${ico('bulb')}<strong>Las buenas preguntas abren caminos.</strong>Primero pensamos. Después exploramos juntos.</div><a class="account" href="#/docente/cuenta" style="text-decoration:none;color:inherit"><span class="avatar">${esc(state.name.charAt(0))}</span><span>${esc(state.name)}<small>Espacio docente</small></span>${ico('settings')}</a></div></aside><main class="main ${step?'wizard-content':''}"><header class="topbar"><span class="row"><button class="circle-button mobile-menu" data-action="mobile-menu" aria-label="Abrir menú">${ico('menu')}</button>Mi espacio / ${step?'Crear actividad':({home:'Inicio',groups:'Mis grupos',activities:'Actividades',progress:'Progreso',settings:'Mi cuenta'}[active])}</span><div class="top-actions"><button class="circle-button" data-action="notifications" aria-label="Notificaciones">${ico('bell')}</button><span class="avatar">${esc(state.name.charAt(0))}</span></div></header><div class="content">${content}</div></main></div>${step?stepper(step):''}`}
function stepper(n){return `<nav class="stepper" aria-label="Pasos de creación de actividad"><div class="stepper-inner">${['Material','Actividad','Revisión','Publicar'].map((s,i)=>`<button class="step ${i+1===n?'current':i+1<n?'done':''}" ${i+1===n?'aria-current="step"':''} data-step="${i+1}" ${i+1>n?'disabled':''}><span class="step-dot">${i+1<n?'✓':i+1}</span>${i+1} · ${s}</button>`).join('')}</div></nav>`}
function student(content,active='home',narrow=false,family=false){return `${preview()}<div class="student-shell"><header class="student-header">${brand()}<div class="top-actions"><span class="pill">${ico(family?'users':'school')}${family?'Espacio familiar':esc(state.group)}</span><a href="#/${family?'familia':'estudiante'}/cuenta" class="circle-button" aria-label="Mi cuenta">${ico('user')}</a></div></header><main class="student-main ${narrow?'narrow':''}">${content}</main>${!family?`<nav class="student-nav" aria-label="Navegación estudiante">${[['home','home','Inicio','/estudiante'],['games','target','Retos','/estudiante/retos'],['progress','chart','Mi avance','/estudiante/avance']].map(([id,ic,label,path])=>`<a class="${active===id?'active':''}" href="#${path}">${ico(ic)}${label}</a>`).join('')}</nav>`:''}</div>`}
function auth(content){return `${preview()}<main class="auth-page"><div class="auth-card">${brand()}${content}</div></main>`}
const head=(tag,title,desc='',right='')=>`<div class="page-heading"><div><div class="eyebrow">${tag}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${right}</div>`;
const back=(to,text='Volver')=>`<a class="back" href="#${to}">${ico('back')}${text}</a>`;
function homeTeacher(){return teacher(`<section class="hero"><div class="hero-copy"><div class="eyebrow">Tu espacio para enseñar a pensar</div><h1>Hoy hacemos<br>buenas preguntas<span style="color:#f5ac31">.</span></h1><p>Diseña actividades que despierten la curiosidad, el análisis y la reflexión de tu grupo.</p>${btn(state.created?'Crear actividad':'Crear mi primer grupo',state.created?'/docente/crear/1':'/docente/grupo/nuevo','primary','plus')}</div>${art('teacher','float')}</section><div class="row card" style="padding:18px 23px"><div class="row">${ico('users')}<strong>${esc(state.group)}</strong><span class="pill">${esc(state.level)}</span></div><a href="#/docente/grupo" class="text-btn">Ver grupo ${ico('chevron')}</a></div><div class="section-heading"><h2>Una forma distinta de aprender</h2><span class="pill">Primero piensan ellos</span></div><div class="cards">${activities.slice(0,2).concat(activities[3]).map(a=>`<a class="card card-link" href="#/docente/crear/2" data-pick="${a.id}" style="padding:22px 22px 0;background:${a.id==='primero'?'#fff7eb':'#f8efff'}"><h3>${a.name}</h3><p>${a.desc}</p>${art(a.pose)}</a>`).join('')}</div><div class="section-heading"><h2>${ico('file')} Para revisar</h2><a class="text-btn" href="#/docente/entregas">Ver entregas ${ico('arrow')}</a></div><div class="card row"><div class="row"><span class="card-icon" style="margin:0">${ico('leaf')}</span><div><strong>La pista de las plantas</strong><p class="mb0" style="font-size:13px">Actividad de ejemplo · Lista para tu revisión</p></div></div>${btn('Revisar actividad','/docente/entregas','secondary','chevron')}</div>`)}
function createGroup(){return teacher(`${back('/docente/grupo')}<div class="form-card"><div class="row"><div><div class="eyebrow">Un nuevo comienzo</div><h1>Crear grupo</h1><p>Define los datos de tu grupo y empieza a explorar.</p></div>${art('think')}</div><form data-form="group">${field('Nombre del grupo','group','Ej. 5.º A',state.group)}<div class="form-grid"><div class="field"><label for="level">Nivel</label><select id="level" name="level"><option ${state.level==='Primaria'?'selected':''}>Primaria</option><option ${state.level==='Secundaria'?'selected':''}>Secundaria</option></select></div><div class="field"><label for="grade">Grado</label><select id="grade" name="grade">${['1.º','2.º','3.º','4.º','5.º','6.º'].map(g=>`<option ${state.grade===g?'selected':''}>${g}</option>`).join('')}</select></div></div><div class="form-actions">${btn('Cancelar','/docente/grupo','secondary','')}<button class="btn primary" type="submit">${ico('check')}Guardar grupo</button></div></form></div>`,'groups')}
function invitation(){return teacher(`${back('/docente/grupo')}<div class="form-card invitation">${art('celebrate')}<div class="eyebrow">Una nueva aventura en equipo</div><h1>${esc(state.group)} ya está listo</h1><p>Comparte el código de invitación con tus estudiantes.</p><div class="code" aria-label="Código de grupo TUK 524">TUK-524</div><div class="invitation-actions">${action('Compartir invitación','share','secondary','share')}${action('Copiar código','copy','secondary','copy')}</div><div class="mt">${btn('Ir a mi grupo','/docente/grupo','primary','arrow')}</div></div>`,'groups')}
function group(){const tabs=`<div class="tabs" role="tablist" aria-label="Secciones del grupo"><button class="tab ${state.tab==='activities'?'selected':''}" role="tab" aria-selected="${state.tab==='activities'}" data-tab="activities">${ico('book')}Actividades</button><button class="tab ${state.tab==='students'?'selected':''}" role="tab" aria-selected="${state.tab==='students'}" data-tab="students">${ico('users')}Estudiantes</button></div>`;return teacher(`${head('Mis grupos',esc(state.group),'Un espacio para observar, preguntar y descubrir.',`<a class="text-btn" href="#/docente/grupo/invitacion">${ico('share')}Compartir grupo</a>`)}${tabs}${state.tab==='activities'?`<section role="tabpanel" aria-label="Actividades del grupo">${state.published?`<div class="card row"><div class="row"><span class="card-icon" style="margin:0">${ico(activities.find(a=>a.id===state.activity).icon)}</span><div><h3>${state.activity==='detective'?'La pista de las plantas':activityName(state.activity)}</h3><span class="pill green">${ico('check')}Publicada</span></div></div>${btn('Ver entregas','/docente/entregas','secondary','chevron')}</div>`:`<div class="card empty">${art('think')}<h2>Aquí empiezan las buenas preguntas</h2><p>Prepara el primer reto para tu grupo.</p></div>`}<div class="form-actions">${btn('Crear actividad','/docente/crear/1','primary','plus')}</div></section>`:`<section role="tabpanel" aria-label="Estudiantes del grupo"><p style="font-size:13px">Pasa el cursor o selecciona un estudiante para ver su correo de registro.</p><div class="student-grid">${[['Alex','alex','A'],['Sol','sol','S'],['Dani','dani','D']].map(([n,email,letter])=>`<button class="student-card" data-action="student-email" aria-label="${n}, ver correo" aria-expanded="false"><span class="avatar">${letter}</span><strong>${n}</strong><span class="email-tooltip">${ico('mail')} ${email}@ejemplo.test</span></button>`).join('')}</div>${art('teacher','group-mascot')}</section>`}`,'groups')}
function wizard(step){let inner='';if(step===1)inner=`${head('Crear actividad','Subir material','Convierte lo que enseñas en una aventura para pensar.')}<form class="form-card" data-form="material"><label class="upload" for="material-file">${ico('upload')}<strong>Sube tu material</strong><span>PDF, foto de un libro o un documento</span><small>También puedes escribir un tema abajo.</small><input type="file" id="material-file" accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.docx" aria-label="Seleccionar material"></label><div class="file-row" id="file-label">${ico('file')}<strong>${esc(state.file||'Las plantas.pdf · Ejemplo')}</strong><button type="button" data-action="remove-file" aria-label="Quitar material">${ico('close')}</button></div><div class="mt">${field('Tema de la actividad','topic','¿Qué tema están explorando?',state.topic)}</div><div class="form-actions"><button type="submit" class="btn primary">Continuar${ico('arrow')}</button></div></form>`;
if(step===2)inner=`${head('Crear actividad','Elegir actividad','Selecciona el tipo de reto que mejor aporte al pensamiento crítico.')}<div class="form-card" style="max-width:100%"><div class="activity-options">${activities.map(a=>`<button class="activity-option ${state.activity===a.id?'selected':''}" data-activity="${a.id}" aria-pressed="${state.activity===a.id}">${ico(a.icon)}<strong>${a.name}</strong>${a.id==='duelo'?'<small>Secundaria · 13+</small>':''}</button>`).join('')}</div><div class="hint mt">${ico('bulb')}<span>${esc(activities.find(a=>a.id===state.activity).desc)} ${state.activity==='duelo'?'Ejemplo para secundaria de 13 años en adelante.':''}</span></div><div class="row mt"><span class="pill">${ico('users')}Grupo ${esc(state.group)}</span>${action('Preparar borrador','prepare','primary','spark')}</div></div>`;
if(step===3)inner=`${head('Crear actividad','Revisa antes de compartir','Confirma que la actividad promueva el análisis y la reflexión.')}<div class="form-card"><span class="pill">${ico('spark')}Propuesta de IA · Ejemplo</span><h3 class="mt">${activityName(state.activity)} · Las plantas</h3><div class="question" id="preview-question">${esc(state.question||'¿Todas las plantas necesitan la misma luz?')}</div><div class="review-block"><h3 style="font-size:17px">${ico('file')} Rúbrica de la actividad</h3><div class="rubric">${['Busca evidencia','Explica','Revisa su idea'].map(s=>`<span>${ico('check')}${s}</span>`).join('')}</div><p class="mt mb0" style="font-size:13px">Tú decides qué preguntas y criterios se comparten con tu grupo.</p></div><div class="form-actions">${action('Editar preguntas','edit-question','secondary','edit')}${btn('Aprobar','/docente/crear/4','primary','check')}</div></div>`;
if(step===4)inner=`${head('Crear actividad','Publicar actividad','Comparte el reto con tu grupo y elige cómo realizarlo.')}<div class="form-card"><div class="file-row" style="margin:0">${ico(activities.find(a=>a.id===state.activity).icon)}<div><span class="muted" style="font-size:13px">${activityName(state.activity)}</span><h3 class="mb0">${state.activity==='detective'?'La pista de las plantas':esc(state.topic)}</h3></div></div><div class="field mt"><label>Grupo</label><div class="pill">${ico('users')}${esc(state.group)}</div></div><label>Modo de trabajo</label><div class="choice-row"><button class="choice ${state.mode==='individual'?'selected':''}" data-mode="individual"><span class="radio"></span>${ico('user')}Individual</button><button class="choice ${state.mode==='classroom'?'selected':''}" data-mode="classroom"><span class="radio"></span>${ico('users')}Proyectar en clase</button></div><p style="font-size:13px;margin:15px 0">${state.mode==='individual'?'Cada estudiante realiza el reto en su dispositivo.':'Guía al grupo desde un solo dispositivo y registra sus ideas.'}</p><div class="row mt"><span class="pill green">${ico('check')}Lista para tu grupo</span>${action('Publicar actividad','publish','primary','share')}</div></div>`;
return teacher(`${back(step===1?'/docente/grupo':'/docente/crear/'+(step-1))}${inner}`,'activities',step)}
function activityList(){return teacher(`${head('Biblioteca docente','Actividades','Cinco maneras de hacer buenas preguntas.',btn('Crear actividad','/docente/crear/1','primary','plus'))}<div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${activities.map(a=>`<a class="card card-link game-card" href="#/docente/crear/2" data-pick="${a.id}" style="background:${a.id==='primero'?'#fff8ee':'#fbf5ff'}">${art(a.pose)}<div class="game-card-text"><h3>${a.name}</h3><p>${a.desc}</p><span class="text-btn">Preparar reto ${ico('arrow')}</span></div></a>`).join('')}</div>`,'activities')}
function deliveries(){return teacher(`${head('Tu grupo en acción','La pista de las plantas',`${esc(state.group)} · Acompaña el proceso de cada estudiante.`)}<div class="row card" style="background:var(--lilac);margin-bottom:22px"><div><h3>Las ideas ya están creciendo</h3><p class="mb0">${Object.keys(state.submitted).length||12} entregas · 4 en proceso</p></div><span class="pill">${ico('clock')}Revisión docente</span></div><div class="card"><table class="table"><thead><tr><th>Estudiante</th><th>Actividad</th><th>Estado</th><th></th></tr></thead><tbody>${['Alex','Sol','Dani'].map((n,i)=>`<tr><td><strong>${n}</strong></td><td>Detective</td><td><span class="pill ${i===0&&state.reviewed?'green':''}">${i===0&&state.reviewed?'Revisado':'Por revisar'}</span></td><td>${btn('Ver entrega','/docente/revisar','secondary small','chevron')}</td></tr>`).join('')}</tbody></table></div>`,'activities')}
function reviewTeacher(){return teacher(`${back('/docente/entregas')}${head('Una mirada a su razonamiento','Revisión de Alex','La pista de las plantas · 5.º A')}<div class="two-col"><div class="card"><span class="pill">${ico('user')}Idea del estudiante</span><div class="question">“${esc(state.answers['detective-explanation']||'La luz influyó en estas plantas.')}”</div>${plants()}<p class="mb0" style="font-size:13px">El estudiante comparó dos observaciones para revisar una afirmación.</p></div><form class="card" data-form="review"><span class="pill">${ico('spark')}Sugerencia de IA · Tú decides</span><h2 class="mt">Tu devolución para Alex</h2>${['Evidencia','Explicación','Reflexión'].map((label,i)=>`<div class="field"><label for="rubric-${i}">${label}</label><select name="rubric-${i}" id="rubric-${i}"><option ${i===0?'selected':''}>Logrado</option><option ${i!==0?'selected':''}>En desarrollo</option><option>Necesita acompañamiento</option></select></div>`).join('')}${area('Una pregunta para seguir pensando','feedback','Escribe una devolución…',state.feedback)}<div class="form-actions"><button type="submit" class="btn primary">${ico('share')}Enviar devolución</button></div></form></div>`,'activities')}
function progressTeacher(){return teacher(`${head('Mirar el proceso','Cómo está pensando el grupo','Cada idea es una oportunidad para seguir aprendiendo.')}<div class="two-col"><div class="card"><span class="pill">${ico('users')}${esc(state.group)}</span><h2 class="mt">Habilidades en crecimiento</h2>${[['Usar evidencia',72],['Explicar ideas',61],['Revisar conclusiones',49]].map(([n,v])=>`<div class="progress-row"><strong>${n}</strong><div class="bar" aria-label="${n}: ${v}% en este ejemplo"><span style="width:${v}%"></span></div></div>`).join('')}<p class="mb0" style="font-size:12px">Vista ilustrativa del grupo · Sin clasificaciones individuales.</p></div><div class="card" style="background:var(--lilac)">${art('think')}<h2>Practiquemos cómo justificar una idea</h2><p>El siguiente reto puede ayudar a conectar las conclusiones con sus evidencias.</p>${btn('Crear siguiente reto','/docente/crear/1','primary','plus')}</div></div><div class="section-heading"><h2>Comparte lo aprendido</h2></div><div class="card row"><div><h3>Un resumen para acompañar</h3><p class="mb0">Muestra a cada familia el proceso de su estudiante.</p></div>${btn('Ver resumen familiar','/familia','secondary','arrow')}</div>`,'progress')}
function startWelcome(){return auth(`${art('wave','float')}<h1>Tu curiosidad<br>abre caminos<span style="color:#f9b140">.</span></h1><p>Observa, pregunta y descubre.</p>${btn('Comenzar','/acceso','primary','arrow')}<div class="auth-bottom"><a href="#/docente">Explorar como docente</a> · <a href="#/estudiante">Explorar como estudiante</a></div>`)}
function chooseRole(){return auth(`<h1>Elige tu espacio</h1><p>Una aventura para aprender a pensar, juntos.</p><div class="stack">${[['teacher','teacher','Soy docente','/ingresar'],['student','wave','Soy estudiante','/unirse'],['family','plant','Soy familiar','/familia/acceso']].map(([r,p,t,path])=>`<a class="role-card" style="text-decoration:none;color:inherit" href="#${path}" data-role="${r}">${art(p)}${t}${ico('chevron')}</a>`).join('')}</div>`)}
function login(register=false){return auth(`${art(register?'think':'teacher')}<h1>${register?'Crear cuenta docente':'Entra a Tutoki'}</h1><form data-form="${register?'register':'login'}">${register?field('Nombre','name','¿Cómo te llamas?',state.name):''}${field('Correo electrónico','email','ana@escuela.test','','email')}${field('Contraseña','password','Tu contraseña','','password')}${register?'<label class="checkline"><input type="checkbox" required> Acepto el aviso de privacidad de esta demostración.</label>':''}<button type="submit" class="btn primary full">${register?'Crear mi espacio':'Iniciar sesión'}${ico('arrow')}</button></form>${btn(register?'Ya tengo una cuenta':'Crear cuenta',register?'/ingresar':'/registro','secondary','')}<div class="auth-bottom">${register?'':`<a href="#/recuperar">Olvidé mi contraseña</a> · `}<a href="#/docente">Entrar a la demostración</a></div>`)}
function join(){return auth(`${art('wave')}<h1>Entra a tu grupo</h1><p>Pide tu código de acceso a tu docente.</p><form data-form="join">${field('Código del grupo','code','TUK-524','TUK-524')}${field('Alias asignado','alias','Tu alias',state.alias)}<div id="join-error" class="error" role="alert"></div><button class="btn primary full" type="submit">Entrar${ico('arrow')}</button></form><div class="auth-bottom">Código de ejemplo: TUK-524</div>`)}
function studentAvatar(){return student(`<div class="center"><span class="pill">${ico('school')}${esc(state.group)} · Profe ${esc(state.name)}</span><h1 class="mt">¡Hola, ${esc(state.alias)}!</h1><p>Elige tu avatar para esta aventura.</p></div><div class="avatar-options">${['detective','speak','think','celebrate'].map(p=>`<button class="avatar-choice ${state.avatar===p?'selected':''}" data-avatar="${p}" aria-label="Avatar ${p}" aria-pressed="${state.avatar===p}">${art(p)}</button>`).join('')}</div>${btn('Guardar avatar','/estudiante','primary full','check')}`,'home',true)}
function studentHome(){return student(`<div class="page-heading"><div><div class="eyebrow">Un nuevo día para descubrir</div><h1>¡Hola, ${esc(state.alias)}!</h1><p>¿Qué buena pregunta harás hoy?</p></div><a href="#/estudiante/avatar" class="circle-button" aria-label="Cambiar avatar">${ico('user')}</a></div><div class="section-heading"><h2>Tu próxima aventura</h2><span class="pill">${ico('school')}De tu docente</span></div><section class="student-hero"><div><span class="pill" style="background:#ffffff88">Busca pistas. Explica tu idea.</span><h2 class="mt">Detective</h2><p>La pista de las plantas</p>${btn(state.submitted.detective?'Volver a explorar':'Empezar','/juego/detective/0','primary','arrow')}</div>${art('detective','float')}</section><div class="two-col mt"><a class="card card-link" href="#/estudiante/retos"><div class="card-icon">${ico('target')}</div><h3>Mis retos</h3><p>Una pregunta. Muchas formas de descubrir.</p></a><a class="card card-link" href="#/estudiante/avance"><div class="card-icon" style="background:var(--cream)">${ico('flag')}</div><h3>Mi recorrido</h3><p>Mira cómo van creciendo tus ideas.</p></a></div>${state.reviewed?`<div class="card mt row"><div><h3>Tu docente te dejó una pregunta</h3><p class="mb0">Un nuevo paso para seguir pensando.</p></div>${btn('Ver devolución','/estudiante/devolucion','secondary','arrow')}</div>`:''}`)}
function gameLibrary(){return student(`${head('De tu docente','Mis retos','Elige una forma de explorar y pon tus ideas en movimiento.')}<div class="cards game-cards">${activities.map(a=>`<a class="card card-link game-card" href="#/juego/${a.id}/0" style="background:${a.id==='primero'?'#fff8ef':'#fbf6ff'}">${art(a.pose)}<div class="game-card-text"><div class="row"><h3>${a.name}</h3><span class="pill ${state.submitted[a.id]?'green':''}">${state.submitted[a.id]?'Enviado':a.id==='duelo'?'13+':'De tu docente'}</span></div><p>${a.desc}</p><span class="text-btn">${state.submitted[a.id]?'Explorar de nuevo':'Explorar reto'}${ico('arrow')}</span></div></a>`).join('')}</div>`,'games')}
function plants(){return `<div class="plant-comparison"><div class="plant-card"><h3>Planta A · Con luz</h3><span class="sun">☀</span><div class="plant-art"><div class="stem"></div><div class="leaf"></div><div class="leaf left"></div><div class="leaf top"></div><div class="pot"></div></div><span class="pill">Día 7 · Misma agua</span></div><div class="plant-card shade"><h3>Planta B · Poca luz</h3><div class="plant-art weak"><div class="stem"></div><div class="leaf"></div><div class="leaf left"></div><div class="leaf top"></div><div class="pot"></div></div><span class="pill">Día 7 · Misma agua</span></div></div>`}
const choice=(value,label,selected,group='answer')=>`<button type="button" class="choice ${value===selected?'selected':''}" data-choice="${esc(value)}" data-choice-group="${group}" aria-pressed="${value===selected}"><span class="radio"></span>${label}</button>`;
const ans=(key)=>state.answers[key]||'';
const gameText=(key,label,placeholder='',required=true)=>area(label,key,placeholder,ans(key),required);
function game(id,step){const a=activities.find(a=>a.id===id);if(!a)return notFound();let content='';const next=step+1;
if(step===0){const intros={detective:['La pista de las plantas','Encuentra una afirmación que necesite revisión.','Investigar',['Lee','Busca pistas','Explica']],primero:['Primero tú','Primero imagina. Después observa.','Mi predicción',['Imagina','Observa','Compara']],duelo:['Duelo de ideas','¿Más áreas verdes en la escuela?','Elegir postura',['Elige','Argumenta','Reconsidera']],defiendelo:['Defiéndelo','Explica cómo llegaste a tu idea.','Comenzar explicación',['Explica','Conecta','Revisa']],comunidad:['Reto comunidad','Un rincón más verde','Explorar el reto',['Observamos','Proponemos','Presentamos']]};const [title,desc,cta,steps]=intros[id];content=`<div class="game-title">${id==='duelo'?'<span class="pill">Secundaria · 13+</span>':''}${art(a.pose,'float')}<h1>${title}</h1><p>${desc}</p></div>${id==='primero'?'<div class="question center">¿Qué pasará si una planta recibe menos luz?</div>':id==='comunidad'?'<div class="question center">¿Cómo mejoraríamos un espacio de la escuela?</div>':''}<div class="game-instructions">${steps.map((s,i)=>`<div class="instruction">${ico(['book','search','bulb'][i])}${s}</div>`).join('')}</div><div class="hint">${ico('school')}Actividad aprobada por tu docente. Lo importante es cómo piensas.</div>${btn(cta,`/juego/${id}/1`,'primary full','arrow')}`}
else if(id==='detective'){
if(step===1)content=`<span class="pill">${ico('file')}Texto para investigar · Contiene un error</span><h2 class="mt">Observa con atención</h2><div class="game-quote">Todas las plantas <button class="word ${ans('detective-word')==='crecen igual'?'selected':''}" data-word="crecen igual">crecen igual</button> aunque reciban <button class="word ${ans('detective-word')==='distinta luz'?'selected':''}" data-word="distinta luz">distinta luz</button>.</div><div class="hint">${ico('search')}Toca la parte que revisarías. Después buscarás evidencia.</div><a class="btn primary full" href="#/juego/detective/2" data-require="detective-word">Buscar evidencia${ico('arrow')}</a>`;
if(step===2)content=`<h2>¿Qué observación ayuda a revisar la frase?</h2>${plants()}<div class="game-options">${choice('different','Crecieron de forma distinta',ans('detective-evidence'),'detective-evidence')}${choice('same','Recibieron la misma cantidad de agua',ans('detective-evidence'),'detective-evidence')}</div><div class="hint">${ico('bulb')}Compara lo que cambió y lo que se mantuvo igual.</div><a class="btn primary full" href="#/juego/detective/3" data-require="detective-evidence">Explicar mi pista${ico('arrow')}</a>`;
if(step===3)content=`<h2>Ahora, explica tu pista</h2><div class="hint">${ico('search')}Elegiste revisar “${esc(ans('detective-word')||'crecen igual')}”. ¿Qué dicen tus observaciones?</div><form data-form="submit-game" data-game="detective">${gameText('detective-explanation','La evidencia me hace pensar que…','Conecta lo que observaste con tu idea.')}${art('celebrate')}<button type="submit" class="btn primary full">Enviar a mi docente${ico('arrow')}</button></form>`;
}else if(id==='primero'){
if(step===1)content=`<h2>Antes de observar</h2><div class="question">¿Qué pasará si una planta recibe menos luz?</div><div class="game-options">${['Crecerá igual','Crecerá diferente','Aún no lo sé'].map(s=>choice(s,s,ans('primero-prediction'),'primero-prediction')).join('')}</div><form data-form="game-next" data-next="/juego/primero/2" class="mt">${gameText('primero-why','¿Por qué lo piensas?','Escribe tu primera idea.')}<button type="submit" class="btn primary full">Guardar predicción${ico('arrow')}</button></form>`;
if(step===2)content=`<h2>Observa y compara</h2><p>Dos plantas del mismo tipo, durante siete días. Cambiamos la luz y mantuvimos la misma cantidad de agua.</p>${plants()}${action('Ver de nuevo','observe-again','soft','play')}<form class="mt" data-form="game-next" data-next="/juego/primero/3">${gameText('primero-observation','¿Qué diferencias notas?','Describe lo que ves.')}<button type="submit" class="btn primary full">Comparar con mi idea${ico('arrow')}</button></form>`;
if(step===3)content=`<h2>Compara con tu primera idea</h2><div class="paper"><strong>Antes pensaba</strong><p class="mb0 mt">${esc(ans('primero-prediction')||'Aún no lo sabía')}. ${esc(ans('primero-why'))}</p></div><form data-form="submit-game" data-game="primero" class="mt">${gameText('primero-now','Ahora pienso','¿Qué cambió o se confirmó?')}${gameText('primero-evidence','¿Qué evidencia cambió o confirmó tu idea?','Explica qué observación te ayudó.')}<button type="submit" class="btn primary full">Enviar reflexión${ico('arrow')}</button></form>`;
}else if(id==='duelo'){
if(step===1)content=`<span class="pill">Secundaria · 13+</span><h2 class="mt">Tu postura</h2><p>¿Más áreas verdes en la escuela?</p><div class="game-options">${choice('Priorizar áreas verdes',ico('leaf')+'Priorizar áreas verdes',ans('duelo-position'),'duelo-position')}${choice('Priorizar otros espacios',ico('school')+'Priorizar otros espacios',ans('duelo-position'),'duelo-position')}</div><form class="mt" data-form="game-next" data-next="/juego/duelo/2">${gameText('duelo-argument','Mi argumento','Pienso esto porque…')}${gameText('duelo-evidence','La evidencia que usaría','¿Qué información respalda tu postura?')}<button type="submit" class="btn primary full">Presentar argumento${ico('arrow')}</button></form>`;
if(step===2)content=`<span class="pill">${ico('spark')}Contrapunto de ejemplo · Puede equivocarse</span><div class="question">${ans('duelo-position')==='Priorizar otros espacios'?'Las áreas verdes también pueden ser espacios para aprender y jugar.':'Un jardín ocupa espacio que podría usarse para jugar.'}</div><form data-form="game-next" data-next="/juego/duelo/3">${gameText('duelo-reply','¿Cómo responderías considerando ambas necesidades?','Escribe tu réplica con evidencia.')}<button type="submit" class="btn primary full">Enviar réplica${ico('arrow')}</button></form>`;
if(step===3)content=`${art('think')}<h2>¿Qué parte de la otra postura vale la pena considerar?</h2><div class="game-options">${['Mantengo mi idea','La ajusto','Necesito más evidencia'].map(s=>choice(s,s,ans('duelo-conclusion-choice'),'duelo-conclusion-choice')).join('')}</div><form class="mt" data-form="submit-game" data-game="duelo">${gameText('duelo-conclusion','Mi conclusión','Explica por qué mantienes o ajustas tu idea.')}<button type="submit" class="btn primary full">Enviar conclusión${ico('arrow')}</button></form><div class="hint">${ico('info')}Sin ganadores: importa cómo argumentas.</div>`;
}else if(id==='defiendelo'){
const labels=['','¿Por qué elegiste esa conclusión?','¿Qué evidencia de tu trabajo la apoya?','¿Qué harías distinto si repitieras el experimento?'];content=`<h2>${labels[step]}</h2>${step===1?`<div class="tabs speech-tabs"><button class="tab ${recording?'':'selected'}" data-action="write-mode">${ico('edit')}Escribir</button><button class="tab" data-action="record">${ico('mic')}Grabar voz</button></div><button class="record ${recording?'recording':''}" data-action="record" aria-label="${recording?'Detener grabación':'Grabar explicación'}">${ico('mic')}</button><div id="audio-status" class="center muted" style="font-size:12px">${recording?'Grabando… Pulsa para detener.':'Puedes escribir tu idea o grabarla.'}</div><div id="audio-preview"></div>`:step===2?`<div class="game-options">${choice('observations','Mis observaciones',ans('defiendelo-evidence'),'defiendelo-evidence')}${choice('prediction','Mi predicción',ans('defiendelo-evidence'),'defiendelo-evidence')}</div>`:''}<form data-form="${step===3?'submit-game':'game-next'}" data-game="defiendelo" data-next="/juego/defiendelo/${next}" class="mt">${gameText('defiendelo-'+step,step===2?'Conecto esta evidencia porque…':'Mi explicación',step===3?'Podría mejorar mi experimento si…':'Explica tu razonamiento.',!(step===1&&recordedUrl))}${step===3?'<span class="pill green">Tus 3 respuestas están listas para revisar</span>':''}<button type="submit" class="btn primary full">${step===3?'Enviar a mi docente':step===2?'Siguiente':'Guardar y seguir'}${ico('arrow')}</button></form>`;
}else if(id==='comunidad'){
if(step===1)content=`<h2>Observamos nuestro entorno</h2><div class="paper center"><span style="font-size:60px">🌳 🏫 ☀️</span><p class="mb0">Piensa en el patio de tu escuela.</p></div><p class="mt">Elijan un problema para explorar:</p><div class="game-options">${['Hay poca sombra','Faltan plantas','Necesitamos investigar'].map(s=>choice(s,s,ans('comunidad-problem'),'comunidad-problem')).join('')}</div><a class="btn primary full" href="#/juego/comunidad/2" data-require="comunidad-problem">Guardar observación${ico('arrow')}</a>`;
if(step===2)content=`${art('plant')}<h2>Proponemos una solución</h2><div class="pill">Problema: ${esc(ans('comunidad-problem')||'Faltan plantas')}</div><form class="mt" data-form="game-next" data-next="/juego/comunidad/3">${gameText('comunidad-idea','Nuestra idea','Un jardín con plantas locales…')}${gameText('comunidad-needs','Qué necesitamos','Materiales, personas y cuidados…')}${gameText('comunidad-ask','A quién preguntar','¿Quién nos puede orientar?')}${action('Pedir orientación al docente','ask-teacher','soft','school')}<button type="submit" class="btn primary full">Preparar propuesta${ico('arrow')}</button></form>`;
if(step===3)content=`<h2>Presentamos nuestra propuesta</h2><div class="paper"><h3>${ico('leaf')}Nuestro rincón verde</h3>${[['Problema',ans('comunidad-problem')],['Idea',ans('comunidad-idea')],['Qué necesitamos',ans('comunidad-needs')],['A quién preguntar',ans('comunidad-ask')]].map(([n,v])=>`<div class="summary-line"><strong>${n}</strong>${esc(v||'Por completar')}</div>`).join('')}</div><form class="mt" data-form="submit-game" data-game="comunidad">${gameText('comunidad-evaluation','¿Cómo sabremos si funciona?','¿Qué observaríamos después?')}<button type="submit" class="btn primary full">Enviar propuesta${ico('arrow')}</button></form>`;
}
if(step<0||step>3)return notFound();const labels={detective:['Instrucciones','Observa','Compara','Explica'],primero:['Instrucciones','Tu predicción','Observa','Compara'],duelo:['Instrucciones','Tu postura','Contrasta','Reconsidera'],defiendelo:['Instrucciones','Pregunta 1 de 3','Pregunta 2 de 3','Pregunta 3 de 3'],comunidad:['Instrucciones','Observamos','Proponemos','Presentamos']};return student(`<div class="game-header"><a class="circle-button" href="#${step?'/juego/'+id+'/'+(step-1):'/estudiante/retos'}" aria-label="Volver">${ico('back')}</a><h2>${step?labels[id][step]:a.name}</h2>${step?`<div class="mini-progress" aria-label="Paso ${step} de 3">${[1,2,3].map(n=>`<span class="${n<=step?'on':''}"></span>`).join('')}</div>`:''}</div><section class="game-stage" data-game-stage="${id}">${content}</section>`,'games',true)}
function complete(){return student(`<div class="game-stage success">${art('celebrate','float')}<span class="pill green">${ico('check')}Enviado a tu docente</span><h1 class="mt">¡Tu idea ha crecido!</h1><p>Observaste, conectaste pistas y explicaste tu forma de pensar.</p><div class="milestones">${[['search','Observé'],['leaf','Usé evidencia'],['bulb','Expliqué mi idea']].map(([i,t])=>`<div class="milestone">${ico(i)}${t}</div>`).join('')}</div><div class="question" style="font-size:18px">¿Qué cambió en tu forma de pensar?</div>${btn('Ver mi recorrido','/estudiante/avance','primary full','arrow')}${btn('Explorar otro reto','/estudiante/retos','secondary full','target')}</div>`,'progress',true)}
function progressStudent(){return student(`${head('Cada idea cuenta','Mi recorrido','Mira todo lo que has aprendido al hacer buenas preguntas.')}<div class="two-col"><div class="card success">${art('celebrate')}<h2>El progreso está en cómo piensas</h2><div class="milestones">${[['search','Observé'],['leaf','Usé evidencia'],['bulb','Revisé mi idea']].map(([i,t])=>`<div class="milestone">${ico(i)}${t}</div>`).join('')}</div></div><div class="stack"><div class="card"><div class="eyebrow">Antes pensaba → Ahora pienso</div><h2>Una idea puede crecer</h2><p>${esc(ans('primero-now')||'Cuando comparas evidencias, puedes confirmar una idea, cambiarla o hacer una pregunta nueva.')}</p>${btn('Ver devolución','/estudiante/devolucion','secondary','arrow')}</div><div class="card"><h3>Mis trabajos</h3>${activities.map(a=>`<div class="setting"><span>${ico(a.icon)}${a.name}</span><span class="pill ${state.submitted[a.id]?'green':''}">${state.submitted[a.id]?'Enviado':'Por explorar'}</span></div>`).join('')}</div></div></div>`,'progress')}
function feedbackStudent(){return student(`${back('/estudiante/avance')}<div class="game-stage">${art('teacher')}<h1>Tu docente te dejó una pregunta</h1><div class="question">${esc(state.feedback)}</div><form data-form="reflection">${gameText('feedback-reflection','Mi siguiente reflexión…','Piensa en lo que podrías observar o mantener igual.')}<button class="btn primary full" type="submit">Responder${ico('arrow')}</button></form><div class="hint">${ico('school')}Ejemplo de devolución · Revisado por ${esc(state.name)}</div></div>`,'progress',true)}
function familyHome(detail=false){if(detail)return student(`${back('/familia')}<div class="game-stage"><h1>Una conversación para casa</h1>${plants()}<div class="paper"><h3>La luz influyó en estas plantas</h3><p class="mb0">${esc(ans('detective-explanation')||'Alex comparó observaciones y explicó su propia idea.')}</p></div><div class="question">¿Qué observaste para llegar a esa idea?</div><div class="hint">${ico('bulb')}Escucha su explicación con curiosidad. Las buenas preguntas ayudan a seguir pensando.</div>${btn('Volver al resumen','/familia','secondary full','back')}</div>`,'home',true,true);return student(`<div class="family-intro"><div><span class="pill">${ico('users')}Espacio familiar</span><h1 class="mt">Así está aprendiendo ${esc(state.alias)}</h1><p>Esta semana explicó una idea con evidencia.</p></div>${art('plant')}</div><div class="card mt"><div class="row"><span class="card-icon">${ico('leaf')}</span><span class="pill green">Revisado por su docente</span></div><h2>Las plantas</h2><p>Una pequeña investigación y muchas preguntas para seguir creciendo.</p>${btn('Ver aprendizaje','/familia/aprendizaje','primary','arrow')}</div><div class="hint">${ico('shield')}Información de ejemplo compartida por la escuela. Este espacio corresponde solo a ${esc(state.alias)}.</div>`,'home',true,true)}
function classroom(){return teacher(`${head('Actividad en el aula','Pensemos en grupo','El docente guía la actividad.',action('Pantalla completa','fullscreen','secondary','eye'))}<div class="form-card" style="max-width:100%"><div class="question center" style="font-size:30px">¿Todas las plantas necesitan la misma luz?</div>${plants()}<div class="row" style="flex-wrap:wrap">${action('Leer en voz alta','read-question','secondary','volume')}${action('Mostrar pista','class-hint','secondary','bulb')}${btn('Siguiente','/aula/reflexion','primary','arrow')}</div><div id="class-hint"></div></div>`,'activities')}
function classroomReflection(){return teacher(`${back('/aula')}${head('Escuchamos distintas ideas','Reflexión en grupo','Comparemos las ideas con curiosidad.')}<form class="form-card" data-form="class-reflection">${gameText('team-1','Idea del equipo 1','Registren su primera explicación.')}${gameText('team-2','Idea del equipo 2','¿Qué perspectiva distinta apareció?')}<div class="question">¿Qué evidencia compara ambas ideas?</div>${gameText('team-reflection','Nuestra reflexión','¿Qué aprendimos al escuchar a los demás?')}<button class="btn primary full" type="submit">Registrar reflexión del grupo${ico('check')}</button></form>`,'activities')}
function settings(role='teacher',sub=''){const base=role==='teacher'?'/docente':'/estudiante';let html='';if(sub==='accessibility')html=`${head('Accesibilidad','Aprender a tu manera','Ajusta este espacio para sentirte a gusto.')}<div class="card"><div class="setting"><span>${ico('volume')}Leer instrucciones</span><button class="switch" role="switch" aria-label="Leer instrucciones" aria-checked="${state.read}" data-setting="read"></button></div><div class="setting"><span>${ico('book')}Texto grande</span><button class="switch" role="switch" aria-label="Texto grande" aria-checked="${state.large}" data-setting="large"></button></div><div class="setting"><span>${ico('play')}Reducir movimiento</span><button class="switch" role="switch" aria-label="Reducir movimiento" aria-checked="${state.motion}" data-setting="motion"></button></div><div class="setting"><label for="volume">Volumen</label><input id="volume" type="range" min="0" max="100" value="${state.volume||70}" style="width:55%;accent-color:var(--purple)"></div><div class="form-actions">${action('Guardar ajustes','save-settings','primary','check')}</div></div>`;
else if(sub==='privacy')html=`${head('Tu espacio, tus decisiones','Privacidad y permisos','Controla la información de esta demostración.')}<div class="card"><h2>Datos guardados en este navegador</h2><p>Los grupos, las respuestas y los ajustes de este prototipo se guardan en tu dispositivo. Los formularios de acceso son una demostración y no crean cuentas.</p><div class="hint">${ico('shield')}Los correos visibles de estudiantes son ejemplos ficticios.</div>${action('Borrar datos de la demostración','reset-confirm','secondary','logout')}</div>`;
else if(sub==='profile')html=`${head('Mi cuenta','Mi perfil','Dale tu toque a este espacio.')}<form class="form-card" data-form="profile">${field(role==='teacher'?'Nombre docente':'Alias','profile-name','Tu nombre',role==='teacher'?state.name:state.alias)}<button class="btn primary" type="submit">Guardar cambios${ico('check')}</button></form>`;
else html=`${head('Tu espacio','Mi cuenta','Todo listo para tu próxima aventura.')}<div class="two-col"><div class="card settings-menu"><span class="pill">${ico('user')}${role==='teacher'?'Docente':'Estudiante'}</span>${[['user','Perfil',base+'/perfil'],['shield','Privacidad y permisos',base+'/privacidad'],['volume','Accesibilidad',base+'/accesibilidad'],['download','Preparar uso sin conexión','/docente/sin-conexion']].map(([i,t,p])=>`<a class="setting" style="text-decoration:none;color:inherit" href="#${p}"><span>${ico(i)}${t}</span>${ico('chevron')}</a>`).join('')}<button class="setting" data-action="help"><span>${ico('help')}Ayuda</span>${ico('chevron')}</button><button class="setting" data-action="logout"><span>${ico('logout')}Cerrar sesión</span>${ico('chevron')}</button></div><div class="card center" style="background:var(--lilac)">${art('think')}<h2>La curiosidad te acompaña</h2><p>Hay muchas formas de mirar una misma idea.</p></div></div>`;return role==='teacher'?teacher(`${sub?back('/docente/cuenta'):''}${html}`,'settings'):student(`${sub?back('/estudiante/cuenta'):''}${html}`,'home',!!sub)}
function offlineSetup(){return teacher(`${back('/docente/cuenta')}${head('Prepara la próxima clase','Preparar uso sin conexión','Guarda una actividad y continúa aunque la conexión cambie.')}<div class="form-card"><div class="file-row">${ico('leaf')}<strong>La pista de las plantas</strong><span class="pill green">Disponible</span></div><div class="hint mt">${ico('info')}Este prototipo puede abrirse directamente desde sus archivos. Las nuevas propuestas de IA no están conectadas.</div><div class="stack mt">${action('Guardar actividad en este navegador','save-offline','primary','download')}${action('Descargar guía imprimible','print-guide','secondary','printer')}${btn('Ver estado sin conexión','/estado/sin-conexion','soft','wifi')}</div></div>`,'activities')}
function connectionState(connected=false){return student(`<div class="game-stage center">${art(connected?'celebrate':'think')}<h1>${connected?'Tus ideas están a salvo':'Estás sin conexión'}</h1><p>${connected?'Tus respuestas de esta demostración están guardadas en este navegador.':'Puedes continuar tu actividad guardada.'}</p><div class="file-row"><strong>${connected?'Respuestas guardadas':'La pista de las plantas'}</strong><span class="pill green">${connected?'En este dispositivo':'Disponible'}</span></div>${btn(connected?'Volver a mis retos':'Continuar',connected?'/estudiante/retos':'/juego/detective/0','primary full','arrow')}<div class="hint">${ico('info')}${connected?'Vista ilustrativa de reconexión.':'Tus respuestas se guardan en este dispositivo.'}</div>${!connected?btn('Ver reconexión','/estado/conectado','secondary full',''):''}</div>`,'games',true)}
function notFound(){return auth(`${art('think')}<h1>Busquemos otro camino</h1><p>Esta pantalla no forma parte del recorrido.</p>${btn('Volver al inicio','/','primary','home')}`)}
const routes=()=>[
['Inicio','/'],['Elegir espacio','/acceso'],['Acceso docente','/ingresar'],['Crear cuenta','/registro'],['Inicio docente','/docente'],['Crear grupo','/docente/grupo/nuevo'],['Invitación','/docente/grupo/invitacion'],['Mi grupo','/docente/grupo'],['1 · Material','/docente/crear/1'],['2 · Actividad','/docente/crear/2'],['3 · Revisión','/docente/crear/3'],['4 · Publicar','/docente/crear/4'],['Entrar al grupo','/unirse'],['Elegir avatar','/estudiante/avatar'],['Inicio estudiante','/estudiante'],['Mis retos','/estudiante/retos'],...activities.map(a=>[a.name,'/juego/'+a.id+'/0']),['Actividad terminada','/estudiante/listo'],['Entregas del grupo','/docente/entregas'],['Revisar entrega','/docente/revisar'],['Avance del grupo','/docente/progreso'],['Mi recorrido','/estudiante/avance'],['Devolución docente','/estudiante/devolucion'],['Espacio familiar','/familia'],['Aprendizaje en familia','/familia/aprendizaje'],['Actividad en el aula','/aula'],['Reflexión en grupo','/aula/reflexion'],['Accesibilidad','/estudiante/accesibilidad'],['Preparar sin conexión','/docente/sin-conexion'],['Sin conexión','/estado/sin-conexion'],['Reconexión','/estado/conectado'],['Cuenta docente','/docente/cuenta']];
function render(){current=location.hash.replace(/^#/,'')||'/';if(current.startsWith('/docente')||current.startsWith('/aula'))state.role='teacher';else if(current.startsWith('/estudiante')||current.startsWith('/juego'))state.role='student';else if(current.startsWith('/familia'))state.role='family';let html;
if(current==='/')html=startWelcome();else if(current==='/acceso')html=chooseRole();else if(current==='/ingresar')html=login();else if(current==='/registro')html=login(true);else if(current==='/recuperar')html=auth(`<h1>Recupera tu acceso</h1><p>Escribe el correo con el que te registraste.</p><form data-form="recover">${field('Correo electrónico','email','tu@escuela.test','','email')}<button class="btn primary full">Enviar instrucciones</button></form>${btn('Volver','/ingresar','secondary','back')}`);else if(current==='/docente')html=homeTeacher();else if(current==='/docente/grupo/nuevo')html=createGroup();else if(current==='/docente/grupo/invitacion')html=invitation();else if(current==='/docente/grupo')html=group();else if(/^\/docente\/crear\/[1-4]$/.test(current))html=wizard(Number(current.split('/').pop()));else if(current==='/docente/actividades')html=activityList();else if(current==='/docente/entregas')html=deliveries();else if(current==='/docente/revisar')html=reviewTeacher();else if(current==='/docente/progreso')html=progressTeacher();else if(current==='/unirse')html=join();else if(current==='/estudiante')html=studentHome();else if(current==='/estudiante/avatar')html=studentAvatar();else if(current==='/estudiante/retos')html=gameLibrary();else if(current.startsWith('/juego/')){const [, ,id,step]=current.split('/');html=game(id,Number(step||0))}else if(current==='/estudiante/listo')html=complete();else if(current==='/estudiante/avance')html=progressStudent();else if(current==='/estudiante/devolucion')html=feedbackStudent();else if(current==='/familia')html=familyHome();else if(current==='/familia/aprendizaje')html=familyHome(true);else if(current==='/familia/acceso')html=auth(`${art('plant')}<h1>Acompañar su curiosidad</h1><p>Explora el aprendizaje que comparte el docente con la familia.</p><form data-form="family-login">${field('Código de invitación familiar','family-code','Código de la escuela','FAM-524')}<button class="btn primary full">Ver aprendizaje${ico('arrow')}</button></form>`);else if(current==='/familia/cuenta')html=student(`${head('Espacio familiar','Mi cuenta','Acompaña su forma de pensar.')}<div class="card settings-menu"><a class="setting" href="#/familia" style="text-decoration:none"><span>${ico('leaf')}Resumen de aprendizaje</span>${ico('chevron')}</a><button class="setting" data-action="logout"><span>${ico('logout')}Cerrar sesión</span></button></div>`,'home',true,true);else if(current==='/aula')html=classroom();else if(current==='/aula/reflexion')html=classroomReflection();else if(current==='/docente/sin-conexion')html=offlineSetup();else if(current==='/estado/sin-conexion')html=connectionState();else if(current==='/estado/conectado')html=connectionState(true);else if(/^\/(docente|estudiante)\/(cuenta|accesibilidad|privacidad|perfil)$/.test(current)){const [,r,s]=current.split('/');html=settings(r==='docente'?'teacher':'student',({accesibilidad:'accessibility',privacidad:'privacy',perfil:'profile'})[s]||'')}else html=notFound();
$('#app').innerHTML=html;document.body.classList.toggle('large-text',state.large);document.body.classList.toggle('reduce-motion',state.motion);document.body.classList.remove('focus-mode');document.title='Tutoki · '+(routes().find(r=>r[1]===current)?.[0]||'Aprender a pensar');window.scrollTo(0,0);persist();if(state.read&&current.startsWith('/juego/')){const title=$('.game-stage h2,.game-stage h1');if(title)speak(title.textContent)}
}
function speak(text){if(!('speechSynthesis'in window))return toast('La lectura en voz alta no está disponible en este navegador.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='es-MX';u.rate=.9;u.volume=(state.volume??70)/100;speechSynthesis.speak(u)}
function celebrate(){if(state.motion||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const d=document.createElement('div');d.className='confetti';d.innerHTML=Array.from({length:30},(_,i)=>`<i style="left:${Math.random()*100}%;animation-delay:${Math.random()*.7}s;transform:rotate(${i*12}deg)"></i>`).join('');document.body.append(d);setTimeout(()=>d.remove(),3500)}
async function handleAction(id,el){switch(id){
case'mobile-menu':$('.sidebar')?.classList.toggle('open');break;
case'close-modal':$('#modal').close();break;
case'tour':modal('Explora Tutoki',`<p>Recorre las vistas con datos de ejemplo. Los cinco minijuegos son caminos alternativos.</p><div class="route-links">${routes().map(([t,p],i)=>`<a href="#${p}" data-action="close-modal"><span class="pill">${String(i+1).padStart(2,'0')}</span>${t}</a>`).join('')}</div>`);break;
case'help':modal('Bienvenido a Tutoki',`<p>Esta es una demostración interactiva de la experiencia. Puedes crear un grupo, publicar un reto, cambiar al espacio estudiante y recorrer los cinco minijuegos.</p><div class="hint">${ico('info')}Las cuentas, los archivos, la IA, los envíos y los correos son ejemplos. Las respuestas se guardan solo en este navegador.</div><div class="stack">${btn('Explorar como docente','/docente','primary','school')}${btn('Explorar como estudiante','/estudiante','secondary','user')}</div>`);break;
case'notifications':modal('Tu grupo está en movimiento',`<div class="card"><h3>Hay ideas por revisar</h3><p>La pista de las plantas · ${esc(state.group)}</p>${btn('Ver entregas','/docente/entregas','primary','arrow')}</div>`);break;
case'student-email':el.classList.toggle('expanded');el.setAttribute('aria-expanded',el.classList.contains('expanded'));break;
case'copy':try{await navigator.clipboard.writeText('TUK-524');toast('Código copiado: TUK-524')}catch{modal('Copia tu código',`<input aria-label="Código del grupo" value="TUK-524" readonly onclick="this.select()"><p class="mt">Selecciona el código y cópialo para compartirlo.</p>`)}break;
case'share':{const text=`Únete al grupo ${state.group} en Tutoki. Código: TUK-524.`;if(navigator.share){try{await navigator.share({title:'Tutoki · Invitación al grupo',text})}catch(e){if(e.name!=='AbortError')toast('Puedes compartir el código TUK-524.')}}else modal('Comparte la invitación',`<p>Tu grupo ya está listo para descubrir.</p><textarea readonly aria-label="Texto de invitación" onclick="this.select()">${esc(text)}</textarea><div class="mt">${action('Copiar código','copy','primary','copy')}</div>`);break;}
case'remove-file':state.file='';persist();$('#file-label').innerHTML=`${ico('file')}<strong>Sin archivo · Puedes usar un tema</strong>`;break;
case'prepare':{el.disabled=true;el.innerHTML='<span>Preparando ejemplo…</span>';setTimeout(()=>go('/docente/crear/3'),850);break;}
case'edit-question':modal('Edita la pregunta',`<form data-form="edit-question">${area('Pregunta para tu grupo','question','Escribe una pregunta abierta',state.question||'¿Todas las plantas necesitan la misma luz?')}<button class="btn primary full" type="submit">Guardar pregunta${ico('check')}</button></form>`);break;
case'publish':state.published=true;state.created=true;persist();celebrate();modal('¡El reto ya está listo!',`<div class="center">${art('celebrate')}<p>${activityName(state.activity)} ya aparece en el grupo ${esc(state.group)}.</p></div><div class="stack">${btn(state.mode==='classroom'?'Abrir en el aula':'Ver como estudiante',state.mode==='classroom'?'/aula':'/estudiante','primary','arrow')}${btn('Volver a mi grupo','/docente/grupo','secondary','users')}</div>`);break;
case'observe-again':$('.plant-comparison').animate([{opacity:.2,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:650});toast('Observa ambas plantas en el mismo día y con la misma agua.');break;
case'ask-teacher':modal('Una pregunta para tu docente',`<p>Conversen con su docente antes de llevar la propuesta a la práctica.</p><div class="question">¿Qué plantas de nuestra región crecerían bien en este espacio?</div><p>Esta es una sugerencia para conversar en el aula.</p>`);break;
case'write-mode':if(recording)await stopRecording();$('#defiendelo-1')?.focus();break;
case'record':await toggleRecording();break;
case'fullscreen':document.body.classList.toggle('focus-mode');if(!document.fullscreenElement){try{await document.documentElement.requestFullscreen()}catch{}}else{try{await document.exitFullscreen()}catch{}}break;
case'read-question':speak('¿Todas las plantas necesitan la misma luz? Compara las dos plantas y explica qué evidencia apoya tu idea.');break;
case'class-hint':$('#class-hint').innerHTML=`<div class="hint">${ico('bulb')}¿Qué cambió entre las plantas? ¿Qué se mantuvo igual?</div>`;break;
case'save-settings':persist();toast('Tus ajustes están guardados.');break;
case'logout':state.role='teacher';persist();go('/acceso');toast('Has vuelto a la selección de espacio.');break;
case'reset-confirm':modal('¿Empezar de nuevo?',`<p>Se borrarán los grupos, las respuestas y los ajustes de esta demostración en este navegador.</p>${action('Borrar y volver al inicio','reset','primary','logout')}`);break;
case'reset':localStorage.removeItem('tutoki-prototype-v1');location.href=location.href.split('#')[0];location.reload();break;
case'save-offline':state.offline=true;persist();toast('Actividad de ejemplo guardada en este navegador.');break;
case'print-guide':{const guide=`TUTOKI — GUÍA DE AULA\n\nLa pista de las plantas\nGrupo: ${state.group}\n\n1. Lee: Todas las plantas crecen igual aunque reciban distinta luz.\n2. ¿Qué parte revisarías?\n3. Compara dos plantas del mismo tipo, en el mismo día y con la misma agua, pero con distinta luz.\n4. ¿Qué observación ayuda a revisar la frase?\n5. Explica: La evidencia me hace pensar que...\n6. ¿Qué otra condición mantendrías igual?\n\nCriterios: usar evidencia, explicar ideas, revisar conclusiones.`;download(new Blob([guide],{type:'text/plain;charset=utf-8'}),'Tutoki-guia-de-aula.txt');toast('Guía descargada. Puedes abrirla e imprimirla.');break;}
}}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();recording=false;$('.record')?.classList.remove('recording');const status=$('#audio-status');if(status)status.textContent='Tu grabación está lista para escuchar.'}
async function toggleRecording(){if(recording)return stopRecording();if(!navigator.mediaDevices?.getUserMedia)return toast('La grabación requiere localhost o una conexión segura. Puedes escribir tu respuesta.');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));if($('#audio-preview'))$('#audio-preview').innerHTML=`<audio controls style="width:100%;margin-top:15px" src="${recordedUrl}"></audio><small>La grabación permanece en esta pestaña.</small>`;$('#defiendelo-1')?.removeAttribute('required');state.answers['defiendelo-voice']='Grabación realizada en esta pestaña';persist()};recorder.start();recording=true;$('.record')?.classList.add('recording');if($('#audio-status'))$('#audio-status').textContent='Grabando… Pulsa de nuevo para detener.'}catch{toast('No se pudo acceder al micrófono. Puedes escribir tu explicación.')}}
document.addEventListener('click',async e=>{const el=e.target.closest('a,button');if(!el)return;
if(el.dataset.require&&!ans(el.dataset.require)){e.preventDefault();return toast('Primero elige una idea para continuar.')}
if(el.dataset.pick){state.activity=el.dataset.pick;persist()}
if(el.dataset.role){state.role=el.dataset.role;persist()}
if(el.dataset.tab){state.tab=el.dataset.tab;persist();render()}
if(el.dataset.activity){state.activity=el.dataset.activity;persist();render()}
if(el.dataset.mode){state.mode=el.dataset.mode;persist();render()}
if(el.dataset.avatar){state.avatar=el.dataset.avatar;persist();render()}
if(el.dataset.step){go('/docente/crear/'+el.dataset.step)}
if(el.dataset.word){state.answers['detective-word']=el.dataset.word;persist();$$('.word').forEach(b=>b.classList.toggle('selected',b===el))}
if(el.dataset.choice){state.answers[el.dataset.choiceGroup]=el.dataset.choice;persist();$$(`[data-choice-group="${el.dataset.choiceGroup}"]`).forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el)})}
if(el.dataset.setting){state[el.dataset.setting]=!state[el.dataset.setting];persist();const scroll=scrollY;render();window.scrollTo(0,scroll)}
if(el.dataset.action){if(el.tagName==='BUTTON')e.preventDefault();await handleAction(el.dataset.action,el)}
if(el.tagName==='A'&&el.hash&&$('#modal').open)$('#modal').close();
});
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(!f.checkValidity()){f.reportValidity();return}const data=Object.fromEntries(new FormData(f));switch(f.dataset.form){
case'group':state.group=data.group;state.grade=data.grade;state.level=data.level;state.created=true;persist();go('/docente/grupo/invitacion');break;
case'material':state.topic=data.topic;persist();go('/docente/crear/2');break;
case'login':state.role='teacher';go('/docente');toast('Bienvenido a la demostración, '+state.name+'.');break;
case'register':state.name=data.name;state.role='teacher';persist();go('/docente');toast('Tu espacio de demostración está listo.');break;
case'recover':modal('Recuperación de acceso',`<p>En la aplicación conectada se enviarían las instrucciones al correo indicado. Puedes seguir explorando esta demostración.</p>${btn('Entrar a la demostración','/docente','primary full','arrow')}`);break;
case'join':if(data.code.trim().toUpperCase()!=='TUK-524'){$('#join-error').textContent='El código está incompleto o venció. Confírmalo con tu docente.';$('#code').setAttribute('aria-invalid','true')}else{state.alias=data.alias;state.role='student';persist();go('/estudiante/avatar')}break;
case'family-login':if(data['family-code'].trim().toUpperCase()!=='FAM-524')toast('Prueba con el código familiar de ejemplo FAM-524.');else go('/familia');break;
case'edit-question':state.question=data.question;persist();$('#modal').close();render();toast('Pregunta actualizada.');break;
case'game-next':Object.assign(state.answers,data);if(f.dataset.next==='/juego/primero/2'&&!ans('primero-prediction'))return toast('Elige tu predicción antes de observar.');if(f.dataset.next==='/juego/duelo/2'&&!ans('duelo-position'))return toast('Primero elige una postura.');persist();go(f.dataset.next);break;
case'submit-game':Object.assign(state.answers,data);state.submitted[f.dataset.game]=new Date().toISOString();if(recording)stopRecording();persist();go('/estudiante/listo');celebrate();break;
case'review':state.feedback=data.feedback;state.rubrics=[data['rubric-0'],data['rubric-1'],data['rubric-2']];state.reviewed=true;persist();toast('Devolución guardada en esta demostración.');go('/docente/entregas');break;
case'reflection':Object.assign(state.answers,data);persist();toast('Tu nueva reflexión está guardada.');go('/estudiante/avance');break;
case'class-reflection':Object.assign(state.answers,data);persist();toast('Reflexión del grupo guardada.');go('/docente/progreso');break;
case'profile':if(state.role==='teacher')state.name=data['profile-name'];else state.alias=data['profile-name'];persist();go(state.role==='teacher'?'/docente/cuenta':'/estudiante/cuenta');toast('Perfil actualizado.');break;
}});
document.addEventListener('input',e=>{if(e.target.tagName==='TEXTAREA'&&e.target.name&&e.target.closest('[data-game-stage]')){state.answers[e.target.name]=e.target.value;persist()}if(e.target.id==='volume'){state.volume=Number(e.target.value);persist()}});
document.addEventListener('change',e=>{if(e.target.id==='material-file'&&e.target.files[0]){state.file=e.target.files[0].name;persist();$('#file-label').innerHTML=`${ico('file')}<strong>${esc(state.file)}</strong><button type="button" data-action="remove-file" aria-label="Quitar material">${ico('close')}</button>`;toast('Material seleccionado para la vista previa.')}});
window.addEventListener('hashchange',()=>{if(recording)stopRecording();if('speechSynthesis'in window)speechSynthesis.cancel();render()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
render();
})();



